import math
def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])
def find_zero(xs: list):
    """
    xs are coefficients of a polynomial.
    find_zero finds x such that poly(x) = 0.
    Returns only one zero point.
    Assumes xs has even number of coefficients and largest non-zero coefficient guarantees a solution.
    """

    def poly_derivative(xs, x):
        if len(xs) <= 1:
            return 0.0
        deriv_coeffs = [i * coeff for i, coeff in enumerate(xs[1:], start=1)]
        return poly(deriv_coeffs, x)
    x = 1.0
    for _ in range(1000):
        fx = poly(xs, x)
        if abs(fx) < 1e-10:
            return round(x, 10)
        dfx = poly_derivative(xs, x)
        if abs(dfx) < 1e-10:
            break
        x = x - fx / dfx
    return round(x, 10)

def move_one_ball(arr):
    if not arr:
        return True
    n = len(arr)
    if n == 1:
        return True
    min_index = arr.index(min(arr))
    for i in range(n):
        current_idx = (min_index + i) % n
        next_idx = (min_index + i + 1) % n
        if arr[current_idx] > arr[next_idx]:
            return False
    return True

def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False
    return [i for i in range(2, n) if is_prime[i]]

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}
    words = test.split()
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    max_count = max(counts.values())
    result = {key: value for key, value in counts.items() if value == max_count}
    return result

