def solve(s):
    has_letter = any((c.isalpha() for c in s))
    if not has_letter:
        return s[::-1]
    result = []
    for c in s:
        if c.isalpha():
            if c.islower():
                result.append(c.upper())
            else:
                result.append(c.lower())
        else:
            result.append(c)
    return ''.join(result)

def monotonic(l: list):
    """Return True if list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if len(l) <= 2:
        return True
    increasing = l[1] > l[0]
    decreasing = l[1] < l[0]
    if not increasing and (not decreasing):
        return False
    for i in range(1, len(l)):
        if increasing:
            if l[i] < l[i - 1]:
                return False
        elif decreasing:
            if l[i] > l[i - 1]:
                return False
    return True

def find_max(words):
